def shapes(g):
    from collections import defaultdict
    cells=defaultdict(list)
    for r,row in enumerate(g):
        for c,v in enumerate(row):
            if v: cells[v].append((r,c))
    # split each color into connected shapes (4-conn)
    res=defaultdict(list)
    for col,pts in cells.items():
        pts=set(pts); seen=set()
        while pts-seen:
            p=next(iter(pts-seen)); stack=[p]; comp=[]
            while stack:
                q=stack.pop()
                if q in seen: continue
                seen.add(q); comp.append(q)
                r,c=q
                for nr,nc in ((r+1,c),(r-1,c),(r,c+1),(r,c-1)):
                    if (nr,nc) in pts and (nr,nc) not in seen: stack.append((nr,nc))
            rs=[r for r,_ in comp]; cs=[c for _,c in comp]
            r0,c0=min(rs),min(cs)
            m=[[0]*(max(cs)-c0+1) for _ in range(max(rs)-r0+1)]
            for r,c in comp: m[r-r0][c-c0]=col
            res[col].append((r0,c0,m))
    return res

